I'll create a `KanbanFilesView` component and add a view toggle to the KanbanGridView.

```vue src/components/kanban/KanbanFilesView.vue
<script setup>
</script>

<template>
  <div class="w-full h-full flex flex-col gap-2 overflow-auto p-2">
    <!-- Header stats -->
    <div class="flex gap-2 items-center flex-wrap">
      <div class="stat bg-base-200 rounded-box p-3 flex-1 min-w-[120px]">
        <div class="stat-title text-xs">Total Files</div>
        <div class="stat-value text-lg">{{ allFiles.length }}</div>
      </div>
      <div class="stat bg-base-200 rounded-box p-3 flex-1 min-w-[120px]">
        <div class="stat-title text-xs">Tasks with Files</div>
        <div class="stat-value text-lg">{{ tasksWithFiles.length }}</div>
      </div>
      <div class="stat bg-base-200 rounded-box p-3 flex-1 min-w-[120px]">
        <div class="stat-title text-xs">Unique Files</div>
        <div class="stat-value text-lg">{{ uniqueFiles.length }}</div>
      </div>
      <div class="grow"></div>
      <!-- Filter input -->
      <div class="input input-sm input-bordered flex items-center gap-2 w-64">
        <i class="fa-solid fa-filter opacity-60"></i>
        <input
          type="text"
          v-model="fileFilter"
          placeholder="Filter files..."
          class="grow bg-transparent outline-none text-sm"
        />
        <span v-if="fileFilter" class="cursor-pointer" @click="fileFilter = ''">
          <i class="fa-regular fa-circle-xmark"></i>
        </span>
      </div>
      <!-- Group toggle -->
      <div class="join">
        <button
          class="btn btn-sm join-item"
          :class="groupBy === 'file' ? 'btn-active' : ''"
          @click="groupBy = 'file'"
        >
          <i class="fa-solid fa-file"></i> By File
        </button>
        <button
          class="btn btn-sm join-item"
          :class="groupBy === 'task' ? 'btn-active' : ''"
          @click="groupBy = 'task'"
        >
          <i class="fa-solid fa-list-check"></i> By Task
        </button>
        <button
          class="btn btn-sm join-item"
          :class="groupBy === 'column' ? 'btn-active' : ''"
          @click="groupBy = 'column'"
        >
          <i class="fa-solid fa-table-columns"></i> By Column
        </button>
      </div>
    </div>

    <!-- Grouped by FILE -->
    <div v-if="groupBy === 'file'" class="flex flex-col gap-2">
      <div
        v-for="group in filteredFileGroups"
        :key="group.file"
        class="collapse collapse-arrow bg-base-200 rounded-box"
      >
        <input type="checkbox" :checked="expandedFiles[group.file]" @change="toggleExpand(group.file)" />
        <div class="collapse-title flex items-center gap-2 py-2 min-h-0">
          <i class="fa-solid fa-file-code text-info text-xs"></i>
          <span class="font-mono text-xs truncate flex-1">{{ group.file }}</span>
          <div class="badge badge-sm badge-neutral ml-auto mr-2">{{ group.tasks.length }} tasks</div>
        </div>
        <div class="collapse-content">
          <div class="flex flex-col gap-1 pt-1">
            <div
              v-for="entry in group.tasks"
              :key="entry.chat.id + entry.source"
              class="flex items-center gap-2 p-2 bg-base-100 rounded-lg cursor-pointer hover:bg-base-300 transition-colors"
              @click="$emit('open-task', entry.chat)"
            >
              <div class="flex-1 min-w-0">
                <div class="text-sm font-medium truncate">{{ entry.chat.name || 'Untitled' }}</div>
                <div class="flex gap-2 items-center mt-1">
                  <div class="badge badge-xs badge-outline">{{ entry.chat.column }}</div>
                  <span class="text-xs opacity-50">{{ sourceLabel(entry.source) }}</span>
                </div>
              </div>
              <i class="fa-solid fa-arrow-right text-xs opacity-40"></i>
            </div>
          </div>
        </div>
      </div>
      <div v-if="!filteredFileGroups.length" class="text-center opacity-50 py-8">
        No files found
      </div>
    </div>

    <!-- Grouped by TASK -->
    <div v-if="groupBy === 'task'" class="flex flex-col gap-2">
      <div
        v-for="entry in filteredTaskGroups"
        :key="entry.chat.id"
        class="collapse collapse-arrow bg-base-200 rounded-box"
      >
        <input type="checkbox" />
        <div class="collapse-title flex items-center gap-2 py-2 min-h-0">
          <i class="fa-solid fa-comment text-primary text-xs"></i>
          <span class="text-sm font-medium flex-1 truncate">{{ entry.chat.name || 'Untitled' }}</span>
          <div class="badge badge-sm badge-outline mr-2">{{ entry.chat.column }}</div>
          <div class="badge badge-sm badge-neutral mr-2">{{ entry.files.length }} files</div>
        </div>
        <div class="collapse-content">
          <div class="flex flex-col gap-1 pt-1">
            <div
              v-for="f in entry.files"
              :key="f.file + f.source"
              class="flex items-center gap-2 p-2 bg-base-100 rounded-lg"
            >
              <i class="fa-solid fa-file-code text-info text-xs w-4"></i>
              <span class="font-mono text-xs flex-1 truncate">{{ f.file }}</span>
              <span class="badge badge-xs badge-ghost">{{ sourceLabel(f.source) }}</span>
            </div>
          </div>
        </div>
      </div>
      <div v-if="!filteredTaskGroups.length" class="text-center opacity-50 py-8">
        No tasks with files found
      </div>
    </div>

    <!-- Grouped by COLUMN -->
    <div v-if="groupBy === 'column'" class="flex flex-col gap-2">
      <div
        v-for="col in filteredColumnGroups"
        :key="col.column"
        class="collapse collapse-arrow bg-base-200 rounded-box"
      >
        <input type="checkbox" checked />
        <div class="collapse-title flex items-center gap-2 py-2 min-h-0">
          <i class="fa-solid fa-table-columns text-secondary text-xs"></i>
          <span class="text-sm font-semibold flex-1">{{ col.column }}</span>
          <div class="badge badge-sm badge-neutral mr-2">{{ col.files.length }} files</div>
        </div>
        <div class="collapse-content">
          <div class="flex flex-col gap-2 pt-1">
            <div v-for="entry in col.tasks" :key="entry.chat.id" class="bg-base-100 rounded-lg p-2">
              <div
                class="flex items-center gap-2 cursor-pointer hover:opacity-80"
                @click="$emit('open-task', entry.chat)"
              >
                <i class="fa-solid fa-comment text-primary text-xs"></i>
                <span class="text-sm font-medium flex-1 truncate">{{ entry.chat.name || 'Untitled' }}</span>
                <div class="badge badge-xs badge-neutral">{{ entry.files.length }}</div>
              </div>
              <div class="flex flex-wrap gap-1 mt-2 pl-5">
                <div
                  v-for="f in entry.files"
                  :key="f.file"
                  class="badge badge-xs badge-ghost font-mono"
                  :title="f.file"
                >
                  {{ shortPath(f.file) }}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div v-if="!filteredColumnGroups.length" class="text-center opacity-50 py-8">
        No files found
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    columns: {
      type: Array,
      default: () => []
    }
  },
  emits: ['open-task'],
  data() {
    return {
      fileFilter: '',
      groupBy: 'file',
      expandedFiles: {}
    }
  },
  computed: {
    // Flatten all tasks from all columns
    allTasks() {
      return this.columns.reduce((acc, col) => acc.concat(col.tasks || []), [])
    },

    // Tasks that have at least one file (from chat.files or messages[].files)
    tasksWithFiles() {
      return this.allTasks.filter(chat => this.getFilesForChat(chat).length > 0)
    },

    // All file entries: { file, chat, source }
    allFiles() {
      return this.tasksWithFiles.reduce((acc, chat) => {
        return acc.concat(this.getFilesForChat(chat))
      }, [])
    },

    // Unique file paths
    uniqueFiles() {
      return [...new Set(this.allFiles.map(f => f.file))]
    },

    // Group by file path -> list of tasks referencing it
    fileGroups() {
      const map = {}
      this.allFiles.forEach(({ file, chat, source }) => {
        if (!map[file]) map[file] = { file, tasks: [] }
        map[file].tasks.push({ chat, source })
      })
      return Object.values(map).sort((a, b) => a.file.localeCompare(b.file))
    },

    // Group by task -> list of files
    taskGroups() {
      return this.tasksWithFiles.map(chat => ({
        chat,
        files: this.getFilesForChat(chat)
      }))
    },

    // Group by column -> tasks with files
    columnGroups() {
      return this.columns
        .map(col => {
          const tasks = (col.tasks || [])
            .map(chat => ({ chat, files: this.getFilesForChat(chat) }))
            .filter(e => e.files.length > 0)
          return {
            column: col.title,
            tasks,
            files: tasks.reduce((a, e) => a.concat(e.files), [])
          }
        })
        .filter(col => col.tasks.length > 0)
    },

    // Filtered versions
    filteredFileGroups() {
      if (!this.fileFilter) return this.fileGroups
      const f = this.fileFilter.toLowerCase()
      return this.fileGroups
        .filter(g => g.file.toLowerCase().includes(f) ||
          g.tasks.some(t => t.chat.name?.toLowerCase().includes(f)))
    },

    filteredTaskGroups() {
      if (!this.fileFilter) return this.taskGroups
      const f = this.fileFilter.toLowerCase()
      return this.taskGroups.filter(e =>
        e.chat.name?.toLowerCase().includes(f) ||
        e.files.some(fi => fi.file.toLowerCase().includes(f))
      )
    },

    filteredColumnGroups() {
      if (!this.fileFilter) return this.columnGroups
      const f = this.fileFilter.toLowerCase()
      return this.columnGroups.map(col => ({
        ...col,
        tasks: col.tasks.filter(e =>
          e.chat.name?.toLowerCase().includes(f) ||
          e.files.some(fi => fi.file.toLowerCase().includes(f))
        )
      })).filter(col => col.tasks.length > 0)
    }
  },
  methods: {
    // Extract all file entries from a chat with their source
    getFilesForChat(chat) {
      const entries = []
      const seen = new Set()

      const addFile = (file, source) => {
        if (!file || seen.has(file + source)) return
        seen.add(file + source)
        entries.push({ file, chat, source })
      }

      // From chat.files (array of strings or objects)
      ;(chat.files || []).forEach(f => {
        const path = typeof f === 'string' ? f : f?.path || f?.name
        if (path) addFile(path, 'chat')
      })

      // From chat.file_list
      ;(chat.file_list || []).forEach(f => {
        const path = typeof f === 'string' ? f : f?.path || f?.name
        if (path) addFile(path, 'file_list')
      })

      // From messages[].files
      ;(chat.messages || []).forEach(msg => {
        ;(msg.files || []).forEach(f => {
          const path = typeof f === 'string' ? f : f?.path || f?.name
          if (path) addFile(path, 'message')
        })
      })

      return entries
    },

    // Toggle expand state for file groups
    toggleExpand(file) {
      this.expandedFiles = {
        ...this.expandedFiles,
        [file]: !this.expandedFiles[file]
      }
    },

    // Human-readable source label
    sourceLabel(source) {
      const labels = { chat: 'Chat files', file_list: 'File list', message: 'Message' }
      return labels[source] || source
    },

    // Shorten a file path to last 2 segments
    shortPath(filePath) {
      const parts = filePath.replace(/\\/g, '/').split('/')
      return parts.slice(-2).join('/')
    }
  }
}
</script>
```

Now update KanbanGridView to add the files view toggle:

```vue src/components/kanban/KanbanGridView.vue
<script setup>
import KanbanColumn from './KanbanColumn.vue'
import KanbanFilesView from './KanbanFilesView.vue'
</script>

<template>
  <div class="w-full h-full flex flex-col gap-2 min-h-0">
    <!-- View switcher toolbar -->
    <div class="flex items-center gap-2">
      <div class="join">
        <button
          class="btn btn-xs join-item"
          :class="activeView === 'board' ? 'btn-active' : ''"
          @click="activeView = 'board'"
          title="Board view"
        >
          <i class="fa-solid fa-table-columns"></i>
        </button>
        <button
          class="btn btn-xs join-item"
          :class="activeView === 'files' ? 'btn-active text-info' : ''"
          @click="activeView = 'files'"
          title="Files view"
        >
          <i class="fa-solid fa-folder-open"></i>
          <span class="ml-1 hidden @sm:inline">Files</span>
          <span class="badge badge-xs ml-1" v-if="totalFiles">{{ totalFiles }}</span>
        </button>
      </div>
      <div class="grow"></div>
    </div>

    <!-- Board view -->
    <div
      v-if="activeView === 'board'"
      class="flex gap-3 overflow-x-auto grow min-h-0 pb-2"
    >
      <KanbanColumn
        v-for="col in columns"
        :key="col.id"
        :column="col"
        :lastUpdatedTaskId="lastUpdatedTaskId"
        @open-task="$emit('open-task', $event)"
        @new-task="$emit('new-task', $event)"
        @edit-column="$emit('edit-column', $event)"
        @move-task="$emit('move-task', $event)"
      />
      <!-- Add column button -->
      <div class="flex-shrink-0 w-64 flex items-start pt-1">
        <button
          class="btn btn-sm btn-dashed w-full opacity-60 hover:opacity-100"
          @click="$emit('new-column')"
        >
          <i class="fa-solid fa-plus"></i> Add Column
        </button>
      </div>
    </div>

    <!-- Files view -->
    <KanbanFilesView
      v-if="activeView === 'files'"
      class="grow min-h-0"
      :columns="columns"
      @open-task="$emit('open-task', $event)"
    />
  </div>
</template>

<script>
export default {
  props: {
    columns: {
      type: Array,
      default: () => []
    },
    lastUpdatedTaskId: {
      type: String,
      default: null
    }
  },
  emits: ['open-task', 'new-task', 'new-column', 'edit-column', 'move-task'],
  data() {
    return {
      activeView: 'board'
    }
  },
  computed: {
    // Count total unique files across all columns for the badge
    totalFiles() {
      const seen = new Set()
      this.columns.forEach(col => {
        ;(col.tasks || []).forEach(chat => {
          ;(chat.files || []).forEach(f => seen.add(typeof f === 'string' ? f : f?.path))
          ;(chat.file_list || []).forEach(f => seen.add(typeof f === 'string' ? f : f?.path))
          ;(chat.messages || []).forEach(msg =>
            (msg.files || []).forEach(f => seen.add(typeof f === 'string' ? f : f?.path))
          )
        })
      })
      seen.delete(undefined)
      seen.delete(null)
      return seen.size || 0
    }
  },
  methods: {}
}
</script>
```

Key design decisions:

1. **`KanbanFilesView`** collects files from three sources per chat:
   - `chat.files` — direct chat attachment
   - `chat.file_list` — file list property
   - `messages[].files` — files attached to individual messages

2. **Three grouping modes**:
   - **By File** — see which tasks reference a specific file
   - **By Task** — see all files per task
   - **By Column** — overview per kanban column

3. **`KanbanGridView`** gets a compact join button toolbar to switch between `board` and `files` views, with a badge showing the total unique file count

4. The `files` view emits `open-task` so clicking a task row opens it in the chat panel just like the board view does
